 before(async () => {
   process.env.MODO_TESTE = '1';
   process.env.DB_PATH = ':memory:';
   server = await criarServidor(0);
   port = server.address().port;
 });

 after(() => {
   server.close();
 });

 beforeEach(async () => {
   await fetch(`http://localhost:${port}/_teste/reset`, { method: 'POST' });
 });

