     method: 'POST',
     headers: { 
       'X-Usuario': 'p-carla',
       'Content-Type': 'application/json'
     },
     body: JSON.stringify({
       titulo: 'Palestra de Teste',
       tipo: 'palestra',
       salaId: 'auditorio',
       vagas: 10,
       encontros: [{
         inicio: '2026-10-19T09:00:00-03:00',
         fim: '2026-10-19T10:00:00-03:00'
       }]
     })
   });

   assert.strictEqual(res.status, 403, JSON.stringify(await res.json()));
 });

