test('POST /atividades com sucesso -> 201 Atividade (R18, R19)', async () => {
  const res = await fetch(`http://localhost:${port}/atividades`, {
    method: 'POST',
    headers: { 
      'X-Usuario': 'org-ana',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
