       tipo TEXT,
       salaId TEXT,
       vagas INTEGER,
       situacao TEXT DEFAULT 'prevista'
     );
     CREATE TABLE IF NOT EXISTS encontros (
       id TEXT PRIMARY KEY,
       atividadeId TEXT,
       inicio TEXT,
       fim TEXT,
       FOREIGN KEY(atividadeId) REFERENCES atividades(id)
     );

