    if (isNaN(inicioDate.getTime()) || isNaN(fimDate.getTime())) {
      return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Data inválida' });
    }

    const duracaoMinutos = (fimDate - inicioDate) / 1000 / 60;
