        return res.status(422).json({ erro: 'ENCONTRO_INVALIDO', mensagem: 'Encontro deve ter entre 1 e 4 horas' });
    }

    const diaInicio = getBrasiliaDateStr(enc.inicio);
    const diaFim = getBrasiliaDateStr(enc.fim);

